package com.hrm.dao;import com.hrm.config.DBConnection;import java.sql.*;import java.util.*;public class ReportDAO{public List<String[]> staffing()throws SQLException{List<String[]>a=new ArrayList<>();String q="SELECT d.department_name,j.job_title,j.target_headcount,COUNT(CASE WHEN e.status='ACTIVE' THEN 1 END),GREATEST(0,j.target_headcount-COUNT(CASE WHEN e.status='ACTIVE' THEN 1 END)) FROM jobs j JOIN departments d ON d.department_id=j.department_id LEFT JOIN employees e ON e.job_id=j.job_id GROUP BY j.job_id,d.department_name,j.job_title,j.target_headcount ORDER BY d.department_name,j.job_title";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q);ResultSet r=p.executeQuery()){while(r.next())a.add(new String[]{r.getString(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5)});}return a;}public List<String[]> projects()throws SQLException{List<String[]>a=new ArrayList<>();String q="SELECT p.project_name,p.required_headcount,COUNT(pa.employee_id),GREATEST(0,p.required_headcount-COUNT(pa.employee_id)) FROM projects p LEFT JOIN project_allocations pa ON pa.project_id=p.project_id GROUP BY p.project_id,p.project_name,p.required_headcount ORDER BY p.project_id";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q);ResultSet r=p.executeQuery()){while(r.next())a.add(new String[]{r.getString(1),r.getString(2),r.getString(3),r.getString(4)});}return a;}public List<String[]> employeesByJob(String job,String text)throws SQLException{return members("j.job_title=?",job,text);}public List<String[]> employeesByJob(String job)throws SQLException{return employeesByJob(job,"");}public List<String[]> employeesByProject(String project,String text)throws SQLException{return members("p.project_name=?",project,text);}public List<String[]> employeesByProject(String project)throws SQLException{return employeesByProject(project,"");}private List<String[]>members(String cond,String value,String text)throws SQLException{List<String[]>a=new ArrayList<>();String q="SELECT CONCAT('NV',LPAD(e.employee_id,4,'0')),e.full_name,j.job_title,d.department_name,COALESCE(pa.role_in_project,'-'),e.status FROM employees e JOIN departments d ON d.department_id=e.department_id JOIN jobs j ON j.job_id=e.job_id LEFT JOIN project_allocations pa ON pa.employee_id=e.employee_id LEFT JOIN projects p ON p.project_id=pa.project_id WHERE "+cond+" AND (?='' OR e.full_name LIKE ? OR CONCAT('NV',LPAD(e.employee_id,4,'0')) LIKE ?) ORDER BY e.employee_id";try(Connection c=DBConnection.getConnection();PreparedStatement ps=c.prepareStatement(q)){ps.setString(1,value);ps.setString(2,text);ps.setString(3,"%"+text+"%");ps.setString(4,"%"+text+"%");try(ResultSet r=ps.executeQuery()){while(r.next())a.add(new String[]{r.getString(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6)});}}return a;}public double totalPaid(int year)throws SQLException{String q="SELECT COALESCE(SUM(net_salary),0) FROM payrolls WHERE status='SENT' AND (?=0 OR pay_year=?)";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setInt(1,year);p.setInt(2,year);try(ResultSet r=p.executeQuery()){r.next();return r.getDouble(1);}}}public int count(String table)throws SQLException{if(!table.matches("employees|departments|projects|payrolls"))throw new IllegalArgumentException();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT COUNT(*) FROM "+table);ResultSet r=p.executeQuery()){r.next();return r.getInt(1);}}}
